import { useRoute, useRouter } from 'vue-router'
import { reactive, ref, watch } from 'vue'

export interface UseListQueryOptions<T> {
  defaults: T
  parse: (query: Record<string, unknown>) => T
  serialize: (state: T) => Record<string, string | undefined>
}

function normalizeQuery(obj: Record<string, unknown>): Record<string, string> {
  const result: Record<string, string> = {}
  for (const key of Object.keys(obj).sort()) {
    const value = obj[key]
    if (value !== undefined && value !== '') {
      result[key] = String(value)
    }
  }
  return result
}

/**
 * 将列表页的分页与筛选状态同步到 URL query。
 *
 * 适用于服务端分页列表：刷新后保持当前页、筛选条件；
 * 浏览器前进/后退也能正确恢复状态。
 */
export function useListQuery<T extends Record<string, unknown>>(options: UseListQueryOptions<T>) {
  const route = useRoute()
  const router = useRouter()

  const page = ref(1)
  const pageSize = ref(10)
  const filters = reactive<T>({ ...options.defaults })

  function parseQuery() {
    const q = route.query as Record<string, unknown>
    const pageVal = parseInt(q.page as string, 10)
    const sizeVal = parseInt(q.page_size as string, 10)
    page.value = Number.isFinite(pageVal) && pageVal > 0 ? pageVal : 1
    pageSize.value = Number.isFinite(sizeVal) && sizeVal > 0 ? sizeVal : 10
    Object.assign(filters as unknown as Record<string, unknown>, options.parse(q))
  }

  function buildQuery(): Record<string, string> {
    const q: Record<string, string> = {}
    if (page.value !== 1) q.page = String(page.value)
    if (pageSize.value !== 10) q.page_size = String(pageSize.value)
    const serialized = options.serialize(filters as unknown as T)
    for (const [key, value] of Object.entries(serialized)) {
      if (value !== undefined && value !== '') {
        q[key] = value
      }
    }
    return q
  }

  let isSyncing = false
  async function syncQuery() {
    if (isSyncing) return
    const target = normalizeQuery(buildQuery())
    const current = normalizeQuery(route.query as Record<string, unknown>)
    if (JSON.stringify(target) === JSON.stringify(current)) return

    isSyncing = true
    await router.replace({ query: target })
    isSyncing = false
  }

  function resetFilters() {
    Object.assign(filters, options.defaults)
    page.value = 1
  }

  watch(() => route.query, parseQuery, { immediate: true })
  watch([page, pageSize], syncQuery)
  watch(filters, syncQuery, { deep: true })

  return {
    page,
    pageSize,
    filters,
    resetFilters,
  }
}
